const pages = [1, 2, 3, 4, 5];
return pages.map(p => ({
  json: {
    url: `https://quotes.toscrape.com/page/${p}/`,
    page: p,
    host: 'quotes.toscrape.com'
  }
}));

// Парсим HTML, полученный от HTTP Request.
// Возвращаем массив items — по одному на каждую цитату.
// URL берём из upstream (Wait), т.к. HTTP Request его не сохраняет.

const results = [];

for (const item of items) {
  // 1. URL — через paired item от Wait
  let url = null;
  try {
    url = $('Wait 2–3 с (джиттер)').item.json.url;
  } catch (e) {
    url = item.json && item.json.url ? item.json.url : 'unknown';
  }

  // 2. HTML — HTTP Request в text mode кладёт ответ в поле data
  let html = '';
  const j = item.json;
  if (typeof j === 'string') html = j;
  else if (j && typeof j.data === 'string') html = j.data;
  else if (j && typeof j.body === 'string') html = j.body;
  else if (j && typeof j.html === 'string') html = j.html;

  if (!html || html.length < 200) {
    results.push({ json: {
      url, text: null, author: null, authorUrl: null, tags: [],
      _parse_error: 'empty_or_invalid_html',
      _html_length: html ? html.length : 0
    }});
    continue;
  }

  // 2a. Детектор блокировки по содержимому
  const MARKERS = ['captcha', 'access denied', 'are you a robot', 'доступ ограничен', 'too many requests'];
  const low = html.toLowerCase();
  const hit = MARKERS.filter(m => low.includes(m));
  if (hit.length) {
    results.push({ json: { url, text: null, author: null, authorUrl: null, tags: [],
      _parse_error: 'block_markers: ' + hit.join(', '), _html_length: html.length } });
    continue;
  }

  // 3. Разбиваем на блоки цитат по открывающему <div class="quote">
  const parts = html.split(/<div[^>]*class="quote"[^>]*>/i);

  if (parts.length <= 1) {
    results.push({ json: {
      url, text: null, author: null, authorUrl: null, tags: [],
      _parse_error: 'no_quote_blocks_found',
      _html_length: html.length
    }});
    continue;
  }

  // 4. Для каждого блока — извлекаем поля
  for (let i = 1; i < parts.length; i++) {
    const block = parts[i];

    const textMatch = block.match(/<span[^>]*class="text"[^>]*>([\s\S]*?)<\/span>/i);
    const text = textMatch ? textMatch[1].trim() : null;

    const authorMatch = block.match(/<small[^>]*class="author"[^>]*>([\s\S]*?)<\/small>/i);
    const author = authorMatch ? authorMatch[1].trim() : null;

    const authorUrlMatch = block.match(/<a[^>]*href="(\/author\/[^"]+)"[^>]*>/i);
    const authorUrl = authorUrlMatch ? 'https://quotes.toscrape.com' + authorUrlMatch[1] : null;

    const tags = [];
    const tagRegex = /<a[^>]*class="tag"[^>]*>([\s\S]*?)<\/a>/gi;
    let m;
    while ((m = tagRegex.exec(block)) !== null) {
      tags.push(m[1].trim());
    }

    if (!text && !author) continue;

    results.push({ json: {
      url,
      text,
      author,
      authorUrl,
      tags,
      tags_count: tags.length,
      text_length: text ? text.length : 0
    }});
  }
}

return results;

return {
  json: {
    ...$json,
    ts: new Date().toISOString(),
    run_id: $execution.id,
    event: 'quote_ok',
    status: 'ok'
  }
};

return {
  json: {
    ...$json,
    ts: new Date().toISOString(),
    run_id: $execution.id,
    event: 'quote_suspicious',
    status: 'warning',
    reason: 'missing_text',
    raw_preview: JSON.stringify($json).slice(0, 200)
  }
};

let url = null;
try { url = $('Wait 2–3 с (джиттер)').item.json.url; } catch (e) { url = $json.url || null; }
return {
  json: {
    ts: new Date().toISOString(),
    run_id: $execution.id,
    event: 'http_error',
    status: 'error',
    url,
    error: $json.error ? ($json.error.message || JSON.stringify($json.error)) : 'unknown'
  }
};

// Сводка прогона из журнальных узлов
const ok = $('Log OK').all().length;
let warn = 0, errs = 0;
try { warn = $('Log Warning').all().length; } catch (e) {}
try { errs = $('Log HTTP Error').all().length; } catch (e) {}
const pages = $('Build URL List').all().length;
return [{ json: { ts: new Date().toISOString(), run_id: $execution.id, event: 'run_summary',
  pages, quotes_ok: ok, suspicious: warn, http_errors: errs,
  status: (ok < 30 || errs > 0 || warn > 0) ? 'red' : 'green' } }];
